            IF TG_OP<>'DELETE' THEN after_bank := to_jsonb(NEW)->>'bank_id'; END IF;
            IF before_bank IS NOT NULL THEN PERFORM "public".check_transition_publication(before_bank); END IF;
            IF after_bank IS NOT NULL AND after_bank IS DISTINCT FROM before_bank THEN
                PERFORM "public".check_transition_publication(after_bank);
            END IF;
            permit:="public".transition_write_permit(COALESCE(after_bank,before_bank));
            IF TG_TABLE_NAME IN ('banks','mental_models','directives','mental_model_history') THEN
