                INSERT INTO "public".memory_transition_bank_origins(bank_id) VALUES(after_bank) ON CONFLICT DO NOTHING;
            ELSIF TG_TABLE_NAME='banks' AND TG_OP='DELETE' THEN
                UPDATE "public".memory_transition_bank_origins SET deleted=true WHERE bank_id=before_bank;
